/* tiles2d: tile maps that collide and tile themselves. Two scenes, generated by make-level.mjs; Start swaps
 * them (a gate picks one with TILES2D_SCENE=room).
 *
 * assets/strip.cwscene is a side-scroller strip: a TileMap2D whose tile_shapes give every tile its collision shape (blocks, two slopes of
 * each steepness, one-way planks, half blocks, hanging wedges) and a TileCollision2D child that turns the cells
 * into Box2D chains, one outline per chunk. A CharacterBody2D runs it from the pad: left stick or d-pad to
 * move, the south button to jump, down and jump to drop through a plank. Crates are RigidBody2Ds on the same
 * tiles. At tick 420 the sample takes a stone ledge away under a crate (three cell edits: one chunk rebuilt).
 *
 * assets/room.cwscene is a room seen from above whose cells name terrains, not tiles: a floor of four random
 * variants, walls from a 47-tile blob set (two variants), moss from a 16-tile corner set on its own layer and a
 * fence from a 16-tile edge set. The scene's autotile picks every tile as it loads. The stick walks a
 * CharacterBody2D round it (moss slows it: the tile set's `slow` value). At tick 300 the sample paints the
 * upper doorway shut with cw_tilemap2d_set_terrain_rect: the wall tiles round it join up and the colliders of
 * that chunk are rebuilt (TILES2D_NO_PAINT=1 leaves it open: the gate's control).
 * A NavigationRegion2D under the map bakes a grid from the walls and the fence. Four scouts (blue) patrol between
 * the far corners of the two chambers on paths of their own, and take the lower doorway once the upper one is
 * shut; ten followers (red) walk one flow field toward the hero, built again when the hero changes cell.
 *
 * Debug fields: hero.pos, hero.floor, hero.one_way, hero.max_x, hero.min_y, hero.plank_lands, hero.drops,
 * hero.wood_ticks (ticks stood on a tile whose tile_data sound is "wood"), tc.chains, tc.segments, tc.chunks, tc.builds,
 * crate.c_y, phys.hash, bench.build_ms (every chunk built again, timed; not compared across hosts).
 * The room: room.pos, room.door_tile (the tile in the doorway's cell), room.wall_tile (the wall cell over it),
 * room.painted, room.east (the hero is in the east chamber), room.moss_ticks, room.map_hash (every cell of the three layers), room.variants (how many of
 * the 4 floor and 2 wall variant sets are on the map), tc.*; nav.walkable, nav.reached (patrol legs done),
 * nav.path_changes, nav.near_hero (followers within 3 cells of the hero), nav.crowd_hash, nav.flow_hash. */
#include <string.h>
#include <time.h>

#include "cartwheel/debug.h"
#include "cartwheel/input.h"
#include "cartwheel/nav2d.h"
#include "cartwheel/physics_nodes.h"
#include "cartwheel/platform.h"
#include "cartwheel/scene2d.h"
#include "cartwheel/scene_file.h"

static struct {
  float pos[2];
  int32_t door_tile, wall_tile, painted, moss_ticks, variants, east, tick;
  uint32_t map_hash;
  int32_t walkable, reached, path_changes, near_hero, hero_cell[2];
  uint32_t crowd_hash, flow_hash;
} R;

static struct {
  cw_action left, right, up, down, jump, swap;
  int32_t frame;
  float pos[2], max_x, min_y, crate_c_y, build_ms;
  int32_t floor, one_way, plank_lands, drops, tick;
  int32_t chains, segments, chunks, builds;
  uint32_t hash;
  int32_t wood_ticks;
} G;

/* a real clock for the timing field (cw_time is the run's virtual clock in a test) */
static double now_ms(void) {
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (double)ts.tv_sec * 1e3 + (double)ts.tv_nsec * 1e-6;
}

/* #region hero */
typedef struct hero {
  bool was_one_way;
  int drop_ticks;
} hero;

static void hero_fixed(cw_node n, void *d, double dt) {
  hero *h = d;
  cw_value v;
  cw_node_get_prop(n, "velocity", &v);
  cw_value floor, one_way;
  cw_node_get_prop(n, "on_floor", &floor);
  cw_node_get_prop(n, "on_one_way", &one_way);
  float vx = cw_input_axis(0, G.left, G.right) * 90.0f;
  float vy = v.v[1] + 700.0f * (float)dt;
  if (cw_action_just_pressed(0, G.jump) && floor.b) {
    if (cw_action_pressed(0, G.down) && one_way.b) {
      h->drop_ticks = 10; /* down and jump on a plank: fall through it */
      G.drops++;
    } else {
      vy = -290.0f;
    }
  }
  cw_node_set(n, "drop_through", cw_val_bool(h->drop_ticks > 0));
  if (h->drop_ticks > 0) h->drop_ticks--;
  cw_node_set(n, "velocity", cw_val_vec2(vx, vy));
  cw_character2d_move_and_slide(n, (float)dt);
  cw_node_get_prop(n, "on_one_way", &one_way);
  if (one_way.b && !h->was_one_way) G.plank_lands++;
  h->was_one_way = one_way.b;
}
static cw_node_type hero_type = { .name = "TileHero", .parent = "CharacterBody2D", .data_size = sizeof(hero),
                                  .fixed_update = hero_fixed };
/* #endregion */

/* #region room_hero */
static void room_hero_fixed(cw_node n, void *d, double dt) {
  (void)d;
  cw_node map = cw_node_get(cw_node_parent(n), "Map");
  /* the moss layer's tile under the hero, and what the tile set says it does to walking */
  cw_vec2 p = cw_node2d_position(n);
  int cx, cy;
  cw_tilemap2d_local_to_cell(map, p, &cx, &cy);
  float slow = cw_tilemap2d_cell_data(map, 1, cx, cy, "slow", 1.0f);
  R.moss_ticks += slow < 1.0f;
  float speed = 80.0f * slow;
  cw_node_set(n, "velocity", cw_val_vec2(cw_input_axis(0, G.left, G.right) * speed, cw_input_axis(0, G.up, G.down) * speed));
  cw_character2d_move_and_slide(n, (float)dt);
}
static cw_node_type room_hero_type = { .name = "RoomHero", .parent = "CharacterBody2D", .fixed_update = room_hero_fixed };
/* #endregion */

/* #region patrol */
static const cw_vec2 POST[2] = { { 40, 232 }, { 440, 40 } }; /* the far corners of the west and east chambers */

static void on_path_changed(cw_node agent, const cw_value *args, int argc, void *user) {
  (void)agent, (void)args, (void)argc, (void)user;
  R.path_changes++;
}

/* a scout that reaches a post turns round for the other */
static void on_target_reached(cw_node agent, const cw_value *args, int argc, void *user) {
  (void)args, (void)argc, (void)user;
  cw_value at;
  cw_node_get_prop(agent, "target_position", &at);
  const cw_vec2 *next = at.v[0] == POST[0].x ? &POST[1] : &POST[0];
  cw_node_set(agent, "target_position", cw_val_vec2(next->x, next->y));
  R.reached++;
}

static void room_start(cw_node room) {
  for (int i = 0; i < 4; i++) {
    cw_node agent = cw_node_get(room, cw_frame_printf("Scout%d/Agent", i));
    cw_connect(agent, "target_reached", agent, NULL, on_target_reached, NULL, 0);
    cw_connect(agent, "path_changed", agent, NULL, on_path_changed, NULL, 0);
    cw_node_set(agent, "target_position", cw_val_vec2(POST[1].x, POST[1].y));
  }
  for (int i = 0; i < 10; i++) cw_node_call(cw_node_get(room, cw_frame_printf("Follower%d/Agent", i)), "follow_flow", NULL, 0, NULL);
}
/* #endregion */

static void room_fixed(cw_tree *t, cw_node room) {
  cw_node map = cw_node_get(room, "Map"), solid = cw_node_get(map, "Solid"), hero_n = cw_node_get(room, "Hero");
  cw_node nav = cw_node_get(map, "Nav");
  if (++R.tick == 1) room_start(room);
  /* #region flow */
  /* one field for every follower: built again only when the hero stands in another cell */
  cw_vec2 hero_at = cw_node2d_position(hero_n);
  int hx, hy;
  cw_tilemap2d_local_to_cell(map, hero_at, &hx, &hy);
  if (R.tick == 1 || hx != R.hero_cell[0] || hy != R.hero_cell[1]) {
    R.hero_cell[0] = hx, R.hero_cell[1] = hy;
    cw_nav_region2d_set_flow_target(nav, hero_at);
  }
  /* #endregion */
  /* #region paint */
  if (R.tick == 300 && !cw_test_env("TILES2D_NO_PAINT")) {
    /* shut the upper doorway: four cells of the wall terrain on map layer 2. The cells round them pick new
     * tiles too, and the TileCollision2D rebuilds the one chunk they are in */
    cw_tilemap2d_set_terrain_rect(map, 2, 14, 3, 15, 4, cw_tilemap2d_terrain(map, "wall"));
    R.painted = 1;
  }
  /* #endregion */
  cw_vec2 p = cw_node2d_position(hero_n);
  R.pos[0] = p.x, R.pos[1] = p.y;
  R.near_hero = 0;
  for (int i = 0; i < 10; i++) {
    cw_vec2 f = cw_node2d_position(cw_node_get(room, cw_frame_printf("Follower%d", i)));
    R.near_hero += (f.x - p.x) * (f.x - p.x) + (f.y - p.y) * (f.y - p.y) < 48 * 48;
  }
  R.walkable = cw_navgrid_get_stats(cw_nav_region2d_grid(nav)).walkable;
  R.crowd_hash = (uint32_t)cw_crowd2d_hash(cw_nav_region2d_crowd(nav));
  R.flow_hash = (uint32_t)cw_flowfield_hash(cw_nav_region2d_flow(nav));
  R.east = p.x > 256; /* in the east chamber, past the wall between them */
  R.door_tile = cw_tilemap2d_get_cell(map, 2, 14, 3);
  R.wall_tile = cw_tilemap2d_get_cell(map, 2, 14, 2);
  int w, h;
  cw_tilemap2d_size(map, &w, &h);
  uint32_t hh = CW_HASH32_INIT, seen = 0;
  for (int l = 0; l < 3; l++)
    for (int y = 0; y < h; y++)
      for (int x = 0; x < w; x++) {
        uint32_t c = cw_tilemap2d_get_raw(map, l, x, y);
        hh = cw_hash32(&c, sizeof c, hh);
        int id = (int)(c & CW_TILE_ID_MASK) - 1;
        if (id >= 12 && id <= 15) seen |= 1u << (id - 12);          /* the floor's four variants */
        if (id >= 16 && id <= 109) seen |= 1u << (4 + (id - 16) / 47); /* the wall's two variant sets */
      }
  R.map_hash = hh;
  R.variants = 0;
  for (uint32_t b = seen; b; b >>= 1) R.variants += (int)(b & 1);
  cw_tile_collision2d_stats s = cw_tile_collision2d_stats_get(solid);
  G.chains = s.chains, G.segments = s.segments, G.chunks = s.chunks, G.builds = s.builds;
  G.hash = cw_world2d_stats(cw_physics2d_world(t)).hash;
}

static void init(void *u) {
  (void)u;
  G.left = cw_action_add("left", 0.3f);
  G.right = cw_action_add("right", 0.3f);
  G.up = cw_action_add("up", 0.5f);
  G.swap = cw_action_add("swap", 0.5f);
  cw_action_bind_text(G.up, "key:up, key:w, pad:up, axis:ly-");
  cw_action_bind_text(G.swap, "key:return, pad:start");
  G.down = cw_action_add("down", 0.5f);
  G.jump = cw_action_add("jump", 0.5f);
  cw_action_bind_text(G.left, "key:left, key:a, pad:left, axis:lx-");
  cw_action_bind_text(G.right, "key:right, key:d, pad:right, axis:lx+");
  cw_action_bind_text(G.down, "key:down, key:s, pad:down, axis:ly+");
  cw_action_bind_text(G.jump, "key:space, pad:south");
  G.min_y = 1e9f;
  cw_debug_f32_array("hero.pos", G.pos, 2);
  cw_debug_i32("hero.floor", &G.floor);
  cw_debug_i32("hero.one_way", &G.one_way);
  cw_debug_f32("hero.max_x", &G.max_x);
  cw_debug_f32("hero.min_y", &G.min_y);
  cw_debug_i32("hero.plank_lands", &G.plank_lands);
  cw_debug_i32("hero.drops", &G.drops);
  cw_debug_i32("hero.wood_ticks", &G.wood_ticks);
  cw_debug_i32("tc.chains", &G.chains);
  cw_debug_i32("tc.segments", &G.segments);
  cw_debug_i32("tc.chunks", &G.chunks);
  cw_debug_i32("tc.builds", &G.builds);
  cw_debug_f32("crate.c_y", &G.crate_c_y);
  cw_debug_u32("phys.hash", &G.hash);
  cw_debug_f32("bench.build_ms", &G.build_ms);
  cw_debug_f32_array("room.pos", R.pos, 2);
  cw_debug_i32("room.door_tile", &R.door_tile);
  cw_debug_i32("room.wall_tile", &R.wall_tile);
  cw_debug_i32("room.painted", &R.painted);
  cw_debug_i32("room.east", &R.east);
  cw_debug_i32("room.moss_ticks", &R.moss_ticks);
  cw_debug_i32("room.variants", &R.variants);
  cw_debug_u32("room.map_hash", &R.map_hash);
  cw_debug_i32("nav.walkable", &R.walkable);
  cw_debug_i32("nav.reached", &R.reached);
  cw_debug_i32("nav.path_changes", &R.path_changes);
  cw_debug_i32("nav.near_hero", &R.near_hero);
  cw_debug_u32("nav.crowd_hash", &R.crowd_hash);
  cw_debug_u32("nav.flow_hash", &R.flow_hash);
}

static void fixed(void *u, double dt) {
  (void)u;
  (void)dt;
  cw_tree *t = cw_scene_app_tree();
  /* a gate's switch arrives with frame 2 on a cart host: the room is asked for then; Start swaps the scenes */
  bool to_room = ++G.frame == 2 && cw_test_env("TILES2D_SCENE") && !strcmp(cw_test_env("TILES2D_SCENE"), "room");
  cw_node room = cw_node_get(cw_tree_root(t), "Room");
  if (to_room || cw_action_just_pressed(0, G.swap)) {
    cw_scene_app_change_scene(cw_node_valid(room) && !to_room ? "strip.cwscene" : "room.cwscene", false);
    R.tick = 0, G.tick = 0;
    R.reached = R.path_changes = 0;
    return;
  }
  if (cw_node_valid(room)) {
    room_fixed(t, room);
    return;
  }
  cw_node root = cw_node_get(cw_tree_root(t), "Strip");
  if (!cw_node_valid(root)) return;
  cw_node map = cw_node_get(root, "Map"), solid = cw_node_get(map, "Solid"), hero_n = cw_node_get(root, "Hero");
  G.tick++;
  /* #region edit */
  if (G.tick == 420)
    for (int x = 54; x <= 56; x++) cw_tilemap2d_set_cell(map, 0, x, 10, -1, 0); /* the ledge under CrateC */
  /* #endregion */
  if (G.tick == 3) {
    /* how long every chunk takes to build: ask for them all again, and time it */
    cw_node_set(solid, "layers", cw_val_int(1));
    double t0 = now_ms();
    cw_tile_collision2d_update(solid);
    G.build_ms = (float)(now_ms() - t0);
  }
  cw_vec2 p = cw_node2d_position(hero_n);
  cw_value v;
  G.pos[0] = p.x, G.pos[1] = p.y;
  cw_node_get_prop(hero_n, "on_floor", &v);
  G.floor = v.b;
  cw_node_get_prop(hero_n, "on_one_way", &v);
  G.one_way = v.b;
  if (p.x > G.max_x) G.max_x = p.x;
  if (p.y < G.min_y) G.min_y = p.y;
  /* #region data */
  /* what the hero stands on: the cell under its feet, then the word the tile set gives that tile */
  int cx, cy;
  cw_tile_collision2d_cell_at(solid, cw_v2(p.x, p.y + 12), cw_v2(0, -1), &cx, &cy);
  const char *sound = G.floor ? cw_tilemap2d_tile_data_text(map, cw_tilemap2d_get_cell(map, 0, cx, cy), "sound") : "";
  /* #endregion */
  G.wood_ticks += !strcmp(sound, "wood");
  cw_tile_collision2d_stats s = cw_tile_collision2d_stats_get(solid);
  G.chains = s.chains, G.segments = s.segments, G.chunks = s.chunks, G.builds = s.builds;
  G.crate_c_y = cw_node2d_position(cw_node_get(root, "CrateC")).y;
  G.hash = cw_world2d_stats(cw_physics2d_world(t)).hash;
}

cw_app_desc cw_main(int argc, char **argv) {
  (void)argc;
  (void)argv;
  cw_scene_register_builtin_types();
  cw_node_type_register(&hero_type);
  cw_node_type_register(&room_hero_type);
  static cw_app_desc base = { .title = "tiles2d", .width = 960, .height = 540, .debug = true, .init = init, .fixed_update = fixed };
  return cw_scene_app("strip.cwscene", &base);
}
